import{_ as a,c as i,o as t,a2 as n}from"./chunks/framework.mqLGQ42V.js";const u=JSON.parse('{"title":"骨骼技巧 (Bone Tips) - Rive 编辑器","description":"操控形状 (Manipulating Shapes) 如何进行骨骼绑定 (Rigging) 非常重要。一个聪明的绑定方案可以让你用更少的关键帧创建动画，使你的工作流更加高效，并保持时间轴的整洁。","frontmatter":{"title":"骨骼技巧 (Bone Tips) - Rive 编辑器","description":"操控形状 (Manipulating Shapes) 如何进行骨骼绑定 (Rigging) 非常重要。一个聪明的绑定方案可以让你用更少的关键帧创建动画，使你的工作流更加高效，并保持时间轴的整洁。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 形状操控, 骨骼技巧"}]]},"headers":[],"relativePath":"editor/manipulating-shapes/bone-tips.md","filePath":"editor/manipulating-shapes/bone-tips.md","lastUpdated":1774838907000}'),o={name:"editor/manipulating-shapes/bone-tips.md"};function s(r,e,l,p,g,h){return t(),i("div",null,[...e[0]||(e[0]=[n('<p>操控形状 (Manipulating Shapes)</p><h1 id="骨骼技巧-bone-tips" tabindex="-1">骨骼技巧 (Bone Tips) <a class="header-anchor" href="#骨骼技巧-bone-tips" aria-label="Permalink to &quot;骨骼技巧 (Bone Tips)&quot;">​</a></h1><p>如何进行骨骼绑定 (Rigging) 非常重要。一个聪明的绑定方案可以让你用更少的关键帧创建动画，使你的工作流更加高效，并保持时间轴的整洁。</p><h2 id="​-使用骨骼控制多个顶点" tabindex="-1"><a href="#use-bones-for-multiple-vertices">​</a> 使用骨骼控制多个顶点 <a class="header-anchor" href="#​-使用骨骼控制多个顶点" aria-label="Permalink to &quot;[​](#use-bones-for-multiple-vertices) 使用骨骼控制多个顶点&quot;">​</a></h2><p>骨骼最强大的功能之一是能够同时驱动多个顶点的变换。如果你发现自己在为大量独立的顶点逐个设置关键帧，这通常意味着你可以通过更优的骨骼设置来简化流程。</p><p>一个好的绑定方案应该能：</p><ul><li>用<strong>一根骨骼的变换替代多个顶点的手动关键帧</strong>。</li><li>在骨骼之间建立清晰的层级关系，使得父级移动时，所有子级自然跟随。</li></ul><h2 id="​-权重的重要性" tabindex="-1"><a href="#importance-of-weighting">​</a> 权重的重要性 <a class="header-anchor" href="#​-权重的重要性" aria-label="Permalink to &quot;[​](#importance-of-weighting) 权重的重要性&quot;">​</a></h2><p>当你使用网格 (Mesh) 和骨骼时，<strong>权重 (Weighting)</strong> 决定了每根骨骼对特定顶点的影响程度。</p><ul><li><strong>权重值为 1</strong>：顶点完全跟随该骨骼移动。</li><li><strong>权重值为 0</strong>：顶点不受该骨骼影响。</li><li><strong>介于 0 和 1 之间</strong>：顶点受该骨骼的部分影响（多根骨骼可以同时影响同一个顶点，产生平滑的混合效果）。</li></ul><p>花时间精细调整权重可以避免变形时出现不自然的&quot;捏合&quot;或&quot;拉伸&quot;。</p><h2 id="​-规划你的绑定" tabindex="-1"><a href="#planning-your-rig">​</a> 规划你的绑定 <a class="header-anchor" href="#​-规划你的绑定" aria-label="Permalink to &quot;[​](#planning-your-rig) 规划你的绑定&quot;">​</a></h2><p>在开始绑定之前，先思考：</p><ol><li><strong>变形点在哪里？</strong> 例如肘部、膝盖、旗杆的节点。</li><li><strong>哪些部件需要独立运动？</strong> 例如手指的每个关节。</li><li><strong>是否需要 IK（反向动力学）？</strong> 例如需要让脚固定在地面上。</li></ol><p>通过提前规划，你可以避免在项目后期推翻重来。</p><p><a href="/docs/editor/manipulating-shapes/bones">骨骼 (Bones)</a><a href="/docs/editor/manipulating-shapes/meshes">网格 (Meshes)</a></p>',16)])])}const c=a(o,[["render",s]]);export{u as __pageData,c as default};
